css:
 .ua-popup {
  position: fixed;
  width: 100%;
  height: 100%;
  top: 0;
  left: 0;
  z-index: 10000;
  overflow-x: hidden;
  overflow-y: auto;
  outline: 0px;
  display: none;
  opacity: 0;
}

 .ua-popup.shade {
  background-color: rgba(0, 0, 0, 0.5);
}

 .ua-popup.is-open {
  display: block;
  opacity: 1;
}

 .ua-popup img {
  width: 100%;
  max-width: 100%;
}

 .ua-popup .ua-popup-window {
  position: relative;
  width: 80%;
  max-width: 500px;
  margin: 5% auto;
  padding: 20px;
  background-color: #ffffff;
  border-radius: 8px;
}

 .ua-popup .btn-close {
  position: absolute;
  top: 10px;
  right: 10px;
  width: 30px;
  height: 30px;
  padding: 8px;
  border: none;
  outline: none;
  cursor: pointer;
  background-color: #999999;
  mask-image: url("data:image/svg+xml;charset=utf8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%20384%20512%22%3E%3Cpath%20fill%3D%22currentColor%22%20d%3D%22M55.1%2073.4c-12.5-12.5-32.8-12.5-45.3%200s-12.5%2032.8%200%2045.3L147.2%20256%209.9%20393.4c-12.5%2012.5-12.5%2032.8%200%2045.3s32.8%2012.5%2045.3%200L192.5%20301.3%20329.9%20438.6c12.5%2012.5%2032.8%2012.5%2045.3%200s12.5-32.8%200-45.3L237.8%20256%20375.1%20118.6c12.5-12.5%2012.5-32.8%200-45.3s-32.8-12.5-45.3%200L192.5%20210.7%2055.1%2073.4z%22%2F%3E%3C%2Fsvg%3E");
  mask-position: center center;
  mask-size: contain;
  mask-repeat: no-repeat;
  box-sizing: border-box;
}

 .btn-popup-wrap {
  text-align: center;
  margin-top: 20px;
}

 .btn-popup {
  width: 320px;
  max-width: 80%;
  margin: 0 auto;
  padding: 16px 20px;
  border: none;
  outline: none;
  cursor: pointer;
  background: linear-gradient(to bottom, #a90329 0%, #b90a33 44%, #dd2650 100%);
  color: #ffffff;
  font-size: 16px;
  line-height: 1;
  border-radius: 100px;
  position: relative;
}

 .btn-popup::before {
  content: "★";
  position: absolute;
  top: calc(50% - 0.7em);
  right: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  width: auto;
  height: 1.4em;
  aspect-ratio: 1/1;
  font-size: 1.5em;
  color: #a90329;
  background: #ffffff;
  border-radius: 50%;
}

 .video-wrapper {
  position: relative;
}

 .video-wrapper>video {
  width: 100%;
  margin: 0 !important;
  padding: 0 !important;
}

 .btn-muted-off {
  display: inline-block;
  position: absolute;
  top: 10px;
  left: 50%;
  transform: translatex(-50%);
  margin: auto;
  padding: 0.8em 1em;
  font-size: 14px;
  font-weight: bold;
  line-height: 1;
  color: #ffffff;
  background-color: #000000;
  border: none;
  border-radius: 8px;
  cursor: pointer;
}

 .btn-muted-off:hover {
  color: #000000;
  background-color: #00adefff;
}

 img {
  margin: 0 auto;
}

img .calcSimulator__area,
.calcSimulator__area * {
  box-sizing: border-box;
}

.calcSimulator__area img {
  width: 100%;
  height: auto;
  vertical-align: bottom;
}

.calcSimulator__area {
  width: 100%;
  height: auto;
  font-size: min(2.5vw, 16px);
  color: #333;
  margin: 0 auto;
  position: relative;
}

.calcSimulator--head__box {
  width: 90%;
  height: auto;
  margin: 1em auto 2em;
}

.calcSimulator__area p+p {
  margin-top: 1em;
}

.calcSimulator__area .text {
  font-size: 1.6em;
  font-weight: bold;
}

.calcSimulator__area label {
  position: relative;
  top: -0.1em;
}

.calcSimulator__area select {
  font-size: 0.8em;
  background: #efefef;
  border: none;
  padding: 0.3em 1.8em 0.3em 0.5em;
  cursor: pointer;
}

.calcSimulator__area label:before,
.calcSimulator__area label:after {
  content: '';
  position: absolute;
  pointer-events: none;
}

.calcSimulator__area label:before {
  top: -0.1em;
  right: 0.35em;
  width: 1.3em;
  height: calc(1em + 0.4em) !important;
  background: #3291B6;
}

.calcSimulator__area label:after {
  top: 48%;
  right: 0.85em;
  width: 0.2em;
  height: 0.2em !important;
  border-width: 0 2px 2px 0;
  border-color: #fff;
  border-style: solid;
  transform: rotate(45deg);
}

.calcSimulator__area p.resultText {
  color: #3291B6;
  font-size: 1.8em;
  font-weight: bold;
}

.calcSimulator__area p.resultText input {
  width: 6em;
  height: 1.5em;
  margin: 0 0.2em;
  background: #fff;
  border: 1px solid #3291B6;
  display: inline-block;
  text-align: center;
  color: #333;
  font-weight: bold;
  font-size: 1em;
}

.calcSimulator__area .topRightImg__box {
  width: 8em;
  height: auto;
  position: absolute;
  top: 24em;
  right: 0;
}

.calcSimulator__area .btmImg__box {
  margin-top: 2em;
}

 .widget-container-asd {
  font-size: clamp(9.6px, 2.5vw, 16px);
  width: min(750px, 100%);
  margin-inline: auto;
  line-height: 1.35;
}

 .always-show-date {
  position: relative;
  background-image: linear-gradient(90deg, #f9f9f9, #e2e2e2);
  border: solid 1px #000;
}

 .always-show-date__wrapper {
  padding: 1em 2em;
}

 .always-show-date__wrapper .headding {
  display: flex;
  align-items: baseline;
  gap: min(25px, 2.5em);
  line-height: 1.35;
}

 .always-show-date__wrapper .headding .date-field {
  display: flex;
  align-items: baseline;
  gap: 5px;
  font-size: 3em;
  font-weight: 600;
}

 .always-show-date__wrapper .headding .date-field [data-suffix] {
  display: flex;
  align-items: baseline;
  gap: 5px;
}

 .always-show-date__wrapper .headding .date-field [data-suffix]::after {
  content: attr(data-suffix);
  font-size: clamp(10.8px, 2.8vw, 18px);
}

 .always-show-date__wrapper .content {
  margin-top: 1em;
}

 .widget-container {
  position: relative;
}

 .widget-container.EDITABLE::before {
  content: "Vidalytics動画埋め込み";
  width: 100%;
  height: 100%;
  border: 1px dashed #666;
  position: absolute;
  display: flex;
  justify-content: center;
  align-items: center;
}

 video.Tech__video {
  height: 100% !important;
  margin-top: 0 !important;
  margin-bottom: 0 !important;
}

.swiper {
  width: calc(100% - 2em);
  height: auto;
  font-size: min(3vw, 16px);
  padding: 0 1em 3em;
}

.swiper-slide {
  display: flex;
  align-items: center;
  justify-content: center;
}

.video__box {
  position: relative;
  width: 90%;
  max-width: 560px;
  aspect-ratio: 16/9;
  overflow: hidden;
  border-radius: 8px;
  background: #fff;
  cursor: pointer;
}

.video__box video {
  width: 100%;
  height: 100% !important;
  margin: 0 !important;
  object-fit: cover;
  display: block;
}

.swiper-button-next,
.swiper-button-prev {
  width: 2em;
  height: 2em;
  border-radius: 1em;
  background-color: #fff;
  box-shadow: 0px 0px 8px rgba(0, 0, 0, 0.2);
  top: calc(50% - 1em);
}

.swiper-button-next {
  right: 5px;
}

.swiper-button-prev {
  left: 5px;
}

.swiper-button-next:after,
.swiper-button-prev:after {
  content: '';
  width: 0.2em;
  height: 0.2em;
  border-color: #D45D87;
  border-style: solid;
  transform: rotate(45deg);
  display: block;
  position: relative
}

.swiper-button-prev:after {
  border-width: 4px 4px 0 0;
  transform: rotate(-135deg);
  right: -2px;
}

.swiper-button-next:after {
  border-width: 4px 4px 0 0;
  transform: rotate(45deg);
  left: -2px;
}

.swiper-pagination-bullet-active {
  background: #D45D87;
}

.swiper {
  display: flex;
  margin-left: auto;
  margin-right: auto;
  position: relative;
  overflow: hidden;
  list-style: none;
  padding: 0;
  width: 100%;
}

.swiper-wrapper {
  position: relative;
  width: 100%;
  height: 100%;
  display: flex;
  transform: translate3d(0, 0, 0);
  transition-property: transform;
  box-sizing: content-box;
  transition-timing-function: linear;
}

.swiper-slide {
  background: #fff;
  flex-shrink: 0;
  width: 100%;
  height: auto;
  position: relative;
  transition-property: transform;
  will-change: transform;
}

.swiper-slide img {
  width: 100%;
  height: auto;
}

.swiper-slide img.lazyload:not(.loaded) {
  width: auto;
  max-width: 100%;
}

.itemDetail__area {
  width: 100%;
  height: auto;
  margin-top: 0.5em;
  font-size: min(3vw, 16px);
}

.itemDetail__area p {
  margin: 0;
}

.itemDetail__area .head1__box,
.itemDetail__area .head2__box {
  width: 100%;
  height: auto;
  padding: 0.2em 0.5em;
  text-align: center;
  color: #fff;
  font-size: 1em;
  box-sizing: border-box;
}

.itemDetail__area .head1__box {
  background-color: #8174A0;
}

.itemDetail__area .head2__box {
  background-color: #EFB6C8;
}

.itemDetail__area .text {
  font-size: 0.9em;
  text-align: center;
  margin: 0.5em 0;
}



/* エディタ編集用の設定 */
.EDITABLE .swiper-wrapper {
  display: grid;
  grid-template-columns: repeat(auto-fit, calc((100% / 6) - 10px));
  gap: 10px;
}

.EDITABLE .swiper-slide {
  margin: 0 5px;
}

.widget-container {
  font-size: 16px;
  width: min(100%, 758px);
  margin-inline: auto;
}

@media (max-width: 480px) {
  .widget-container {
    font-size: 3.3vw;
  }
}

.loop-number-content {
  background-color: #034a04;
  padding: 2em 2em 1em;
  position: relative;
}

.loop-number-content .title {
  font-size: 1.085rem;
  background-color: #fff;
  border: 1px solid #034a04;
  width: min(100%, 330px);
  text-align: center;
  padding: 0.5em 2em;
  line-height: 1;
  border-radius: 99px;
  position: absolute;
  top: 0;
  left: 50%;
  transform: translate(-50%, -50%);
}

.loop-number-wrapper {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 0.5em;
  color: #fff;
}

.loop-number-wrapper .numbers {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 0.25em;
}

.loop-number-wrapper .numbers .item {
  width: 46.4px;
  background-size: 46.4px;
  aspect-ratio: 58/100;
  overflow: hidden;
  background-color: #231815;
  background-repeat: no-repeat;
  background-position: 0 0;
  background-image: url("/uploads/b4610affffd37a615a3148806ecd07d60aba73b94cafe89b84d9560af98412fb.webp");
  animation: slot 0.75s steps(9) infinite;
  animation-delay: calc(var(--delay, 0) * 1s);
}

.loop-number-wrapper .before-text,
.loop-number-wrapper .after-text {
  line-height: 1.25;
}

@media (max-width: 480px) {
  .loop-number-wrapper .numbers .item {
    width: 35px;
    background-size: 35px;
    animation: slot_mb 0.75s steps(9) infinite;
    animation-delay: calc(var(--delay, 0) * 1s);
  }
}


@keyframes slot {
  from {
    background-position-y: -80px;
  }

  to {
    background-position-y: -800px;
  }
}

@keyframes slot_mb {
  from {
    background-position-y: -60px;
  }

  to {
    background-position-y: -600px;
  }
}

* {
  box-sizing: border-box;
}

 .add-time-countdown {
  width: 100%;
  height: auto;
  margin: 0 auto;
  padding: 10px 0;
  background: #ffec47;
  text-align: center;
  display: flex;
  justify-content: center;
  align-items: center;
}

 .add-time-countdown p {
  color: #000;
  font-size: min(5vw, 30px);
  font-weight: bold;
  margin: 0;
  letter-spacing: 0.05em;
  line-height: 1;
}

 .add-time-countdown p span {
  display: inline-block;
  color: #e83929;
  background: #ffffff;
  padding: 0.2em 0.2em 0.1em;
  margin: 0 0.1em;
  line-height: 1;
}

.widget-container {
  font-size: 18px;
  width: muin(750px, 100%);
}


@media (max-width: 500px) {
  .widget-container {
    font-size: 3.6vw;
  }
}

.vertical-loop-text-wrap {
  width: fit-content;
  height: 100vh;
  background-color: #000;
  color: #fff;
  writing-mode: vertical-rl;
  position: fixed;
  top: 0;
  right: 0;
  z-index: 100;
  overflow: hidden;
  letter-spacing: 0.25em;
  display: flex;
}

.vertical-loop-text-wrap.animate .vertical-loop-text-item {
  animation: verticalLoop var(--loop-time, 10s) 1s linear infinite;
}

.vertical-loop-text-item {
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0;
  flex-shrink: 0;
  margin: 0.5em 0;
  text-align: center;
}

.vertical-loop-text-close {
  position: absolute;
  bottom: 0;
  right: 0;
  cursor: pointer;
  z-index: 101;
  width: 100%;
  aspect-ratio: 1;
  background-color: #000;
  display: grid;
  place-items: center;
  font-size: 24px;
  color: #fff;
}

* {
  box-sizing: border-box;
}

div {
  max-width: unset;
}

@keyframes verticalLoop {
  0% {
    transform: translateY(0);
  }

  99.99% {
    transform: translateY(-100%);
  }

  100% {
    transform: translateY(0);
  }
}

 .auto-form-calc {
  max-width: 600px;
  margin: 0 auto;
  box-sizing: border-box;
  text-align: center;
}

 .auto-form-calc .list-radio {
  list-style-type: none;
  margin: 0;
  padding: 10px 0 20px;
  box-sizing: border-box;
  display: flex;
  justify-content: center;
  text-align: center;
  box-sizing: border-box;
}

 .auto-form-calc .list-radio li {
  flex-basis: 25%;
  padding: 0 1%;
}

 .auto-form-calc .list-radio input[type=radio] {
  display: none;
}

 .auto-form-calc .list-radio input[type=radio]:checked+span:before {
  background-color: #3197ee;
  box-shadow: inset 0 0 0 4px #f4f4f4;
}

 .auto-form-calc .list-radio label {
  display: block;
  cursor: pointer;
}

 .auto-form-calc .list-radio label span {
  display: flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
  margin: 0.5em 0;
}

 .auto-form-calc .list-radio label span:before {
  content: "";
  background: #f4f4f4;
  border-radius: 100%;
  border: 1px solid #b4b4b4;
  display: inline-block;
  width: 1em;
  height: 1em;
  position: relative;
  top: 0;
  margin-right: 0.2em;
  vertical-align: top;
  text-align: center;
  transition: all 250ms ease;
}

 .result-box {
  display: inline-block;
  font-size: 1.5em;
  font-weight: bold;
  line-height: 1.2;
  text-align: left;
}

 .result-box .ten-years {
  margin: 20px 0 0;
}

 .result-box .total {
  display: block;
  color: #cc3300;
  text-align: center;
  border: 2px solid #666666;
  border-radius: 4px;
  padding: 10px;
  margin: 10px 0;
  box-shadow: rgba(99, 99, 99, 0.2) 0px 2px 8px 0px;
  box-sizing: border-box;
}

 .result-box [data-calc] {
  font-size: 1.2em;
  font-weight: bold;
  padding: 0 0.5em;

}

.widget-container {
  font-size: 16px;
  width: 100vw;
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  opacity: 0;
  pointer-events: none;
}

.widget-container.is-scrolled {
  opacity: 1;
  pointer-events: auto;
  transition: 0.3s;
}

.swiper {
  display: flex;
  margin-inline: auto;
  position: relative;
  overflow: hidden;
  list-style: none;
  padding: 0;
  width: 100%;
}

.swiper-wrapper {
  position: relative;
  width: 100%;
  height: 100%;
  display: flex;
  transform: translate3d(0, 0, 0);
  transition-property: transform;
  box-sizing: content-box;
  transition-timing-function: linear;
}

.swiper-slide {
  background: #fff;
  flex-shrink: 0;
  width: 100%;
  position: relative;
  transition-property: transform;
  will-change: transform;
  box-shadow: 0 0 3px 1px rgba(0, 0, 0, 0.1);
}

.swiper-slide a {
  text-decoration: none !important;
  color: #333;
  transition: opacity 0.3s;
}

.swiper-slide a:hover {
  opacity: 0.7;
}

.swiper-slide img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
}

.swiper-slide .image-wrap {
  width: 100%;
}

.swiper-slide .info-wrap {
  width: 100%;
  padding: 0.5em 1.5em;
}

.js-scroll-indicator {
  position: fixed;
  top: 50%;
  right: 10px;
  padding: .5em 1em;
  background: white;
  text-align: center;
  border-radius: .5em;
}



/* エディタ編集用の設定 */
.EDITABLE.widget-container {
  opacity: 1;
  pointer-events: auto;
  transition: unset;
}

.EDITABLE .swiper-wrapper {
  overflow-x: scroll;
  padding: 1em;
}

.EDITABLE .swiper-slide {
  margin: 0 5px;
  width: calc(100% / 3.5);
}

.swiper {
  display: flex;
  margin-left: auto;
  margin-right: auto;
  position: relative;
  list-style: none;
  overflow: hidden;
  padding: 20px 35px;
  width: calc(100% - 70px);
  border-radius: 10px;
  border-top: 3px solid #009250;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.1);
  color: #333;
  font-size: 14px;
}

@media screen and (max-width:600px) {
  .swiper {
    font-size: 12px;
  }
}

.swiper:before,
.swiper:after {
  content: '';
  width: 35px;
  height: 100%;
  position: absolute;
  top: 0;
  display: block;
  background-color: #fff;
  z-index: 1;
}

.swiper:before {
  left: 0;
}

.swiper:after {
  right: 0;
}

.swiper-wrapper {
  position: relative;
  width: 100%;
  height: auto;
  display: flex;
  transform: translate3d(0, 0, 0);
  transition-property: transform;
  box-sizing: content-box;
}

.swiper-slide {
  border: 1px solid #333;
  background: #fff;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  flex-shrink: 0;
  width: 100%;
  height: auto;
  box-sizing: border-box;
  position: relative;
  transition-property: transform;
}

.swiper-slide img {
  width: 100%;
  height: auto;
}

.swiper-slide img.lazyload:not(.loaded) {
  width: auto;
  max-width: 100%;
}

.swiper-button-next,
.swiper-button-prev {
  position: absolute;
  top: 50%;
  cursor: pointer;
}

.swiper-button-next {
  right: 10px;
  left: auto;
  outline: none;
}

.swiper-button-prev {
  left: 10px;
  right: auto;
  outline: none;
}

.swiper-button-next::before,
.swiper-button-prev::before {
  content: ' ';
  width: 20px;
  height: 20px;
  position: absolute;
  z-index: 10;
}

.swiper-button-next::before {
  border-right: solid 4px #42AAC7;
  transform: translateY(-50%) rotate(45deg);
  right: 0;
}

.swiper-button-prev::before {
  border-left: solid 4px #42AAC7;
  transform: translateY(-50%) rotate(-45deg);
  left: 0;
}

.swiper-button-next::after,
.swiper-button-prev::after {
  content: ' ';
  width: 20px;
  height: 20px;
  position: absolute;
  top: 3px;
  z-index: 10;
}

.swiper-button-next::after {
  border-right: solid 4px #42AAC7;
  transform: translateY(-50%) rotate(-45deg);
  right: 0;
}

.swiper-button-prev::after {
  border-left: solid 4px #42AAC7;
  transform: translateY(-50%) rotate(45deg);
  left: 0;
}

.swiper-slide .itemDetail {
  width: 100%;
  height: auto;
  margin-top: 0.5em;
  border-style: solid;
  border-color: #eee;
  border-width: 0 1px 1px 1px;
  border-collapse: collapse;
}

.swiper-slide .itemDetail th {
  border-top: 1px solid #eee;
  width: 25%;
  background-color: #C6EDDB;
  text-align: center;
  margin-top: 1px solid #eee;
  padding: 0.2em 0;
}

