.animate-in {
  opacity: 0;
  will-change: clip-path, transition, opacity, translate;
  overflow: hidden;
}

.is-hide {
  opacity: 0 !important;
}

.scroll-in.fade-in {
  animation: fadeIn 1s forwards;
}

.scroll-in.fade-in-left {
  animation: fadeInLeft 1s forwards;
}

.scroll-in.fade-in-right {
  animation: fadeInRight 1s forwards;
}

.scroll-in.fade-in-up {
  animation: fadeInUp 1s forwards;
}

.scroll-in.fade-in-down {
  animation: fadeInDown 1s forwards;
}

.scroll-in.clip-in-left {
  opacity: 1;
  animation: clipInLeft 1s forwards;
}

.scroll-in.clip-in-right {
  opacity: 1;
  animation: clipInRight 1s forwards;
}

.scroll-in.clip-in-up {
  opacity: 1;
  animation: clipInUp 1s forwards;
}

.scroll-in.clip-in-down {
  opacity: 1;
  animation: clipInDown 1s forwards;
}

.flex {
