}

.EDITABLE [class*="animate-in"] {
  opacity: 1;
  translate: 0 0 !important;
  clip-path: inset(0% 0% 0% 0%) !important;
}



@keyframes fadeIn {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}



@keyframes fadeInLeft {
  from {
    opacity: 0;
    translate: -50px 0;
  }

  to {
    opacity: 1;
    translate: 0 0;
  }
}



@keyframes fadeInRight {
  from {
    opacity: 0;
    translate: 50px 0;
  }

  to {
    opacity: 1;
    translate: 0 0;
  }
}


@keyframes fadeInUp {
  from {
    opacity: 0;
    translate: 0 50px;
  }

  to {
    opacity: 1;
    translate: 0 0;
  }
}


@keyframes fadeInDown {
  from {
    opacity: 0;
    translate: 0 -50px;
  }

  to {
    opacity: 1;
    translate: 0 0;
  }
}


@keyframes clipInLeft {
  from {
    opacity: 1;
    clip-path: inset(0% 100% 0% 0%);
  }

  to {
    opacity: 1;
    clip-path: inset(0% 0% 0% 0%);
  }
}


@keyframes clipInRight {
  from {
    opacity: 1;
    clip-path: inset(0% 0% 0% 100%);
  }

  to {
    opacity: 1;
    clip-path: inset(0% 0% 0% 0%);
  }
}


@keyframes clipInUp {
  from {
    opacity: 1;
    clip-path: inset(100% 0% 0% 0%);
  }

  to {
    opacity: 1;
    clip-path: inset(0% 0% 0% 0%);
  }
}



@keyframes clipInDown {
  from {
    opacity: 1;
    clip-path: inset(0% 0% 100% 0%);
  }

  to {
    opacity: 1;
    clip-path: inset(0% 0% 0% 0%);
  }
}

