   border-radius: 4px;
   position: absolute;
   /* 要素の位置（上基準） */
   top: 50%;
   /* 要素の位置（左基準） */
   left: 10px;
   /* 要素の移動 */
   transform: translateY(-50%);
 }



 /* 擬似的チェックボックのチェックマーク */
 .item label:after {
   display: block;
   content: "";
   /* 横幅 */
   width: 6px;
   /* 高さ */
   height: 12px;
   /* 右線｜太さ｜線種｜色｜ */
   border-right: 3px solid rgba(13, 48, 15, .26);
   /* 下線｜太さ｜線種｜色｜ */
