   position: absolute;
   /* 要素の位置（上基準） */
   top: 48%;
   /* 要素の位置（左基準） */
   left: 19px;
   /* 要素の移動 */
   transform: translateY(-48%) rotate(45deg);
   z-index: 10;
 }



