  margin-right: 10px;
  /* 内側の余白|上下|左右| */
  padding: 0 0.3rem;
  line-height: 1;
}

.datewithframe .frame span {
  /* アニメーション設定|名前|時間|種類|カウントinfinite=ループ| */
  animation: blink 0.8s ease infinite;
}

/* 日付 */
.datewithframe .date {
  /* 文字サイズ */
  font-size: 1rem;
  /* 文字の太さ|bold=太め|normal=普通| */
  font-weight: normal;
  /* 文字色 */
  color: #000;
}

/* アニメーション内容 */
@keyframes blink {
  0% {
    opacity: 0;
  }
  49% {
    opacity: 0;
  }
  50% {
    opacity: 1;
  }
  100% {
    opacity: 1;
  }
}

/* widget全体 */
.countdown__box {
  /* 外側上下左右の余白 */
  margin: 0;
  /* 内側上下左右の余白 */
  padding: 0;
  /* 最大幅 */
  max-width: 100%;
  display: flex;
  /*水平方向に間隔を配置する方法。
  flex-start = 左側から配置する
  flex-end = 右側から配置する
  center = 真ん中に配置する
  space-around = 均等配置して両端に間隔を置く
  space-between = 均等配置してエリアの間に間隔を置く
  space-evenly = 均等配置して各アイテム周りに間隔を置く*/
  justify-content: center;
  /*垂直方向にの配置位置を設定。
  center = 中央配置
  flex-start = 先頭にまとめる
  flex-end = 末尾にまとめる*/
  align-items: flex-start;
}



