/* ウィジェット全体 */
.quizWrap {
  /* 幅 */
  width: 100%;
  /* 最大幅 */
  max-width: 600px;
  /* 外側の余白|上|左右(auto=自動)|下| */
  margin: 0 auto 30px;
}

/* 問題文 */
.quizWrap .quiz_ttl {
  /* 文字サイズ */
  font-size: 20px;
  /* 外側下の余白 */
  margin-bottom: 10px;
}

/* 選択肢 */
.quizWrap .choicebox {
  /* 文字サイズ */
  font-size: 20px;
  /* 背景色 */
  background: #f7f8ff;
  display: flex;
  align-items: center;
  justify-content: flex-start;
  position: relative;
}

/* 奇数の選択肢 */
.quizWrap .choicebox:nth-child(odd) {
  /* 背景色 */
  background: #ddd;
}

/* 選択肢の○×表示部分 */
.quizWrap .choicebox input {
  /* 幅 */
  width: 50px;
  /* 高さ */
  height: 50px;
  /* 外側の余白|上下左右| */
  margin: 0;
  /* 内側の余白|上下左右| */
  padding: 0;
  flex-shrink: 0;
  display: block;
  appearance: none;
  position: relative;
  box-sizing: border-box;
}

/* 偶数の選択肢のチェックマークと×表示部分 */
.quizWrap .choicebox:nth-child(even) input {
  /* 背景色 */
  background-color: #f7f8ff;
}

/* 正解の場合のチェックマーク */
.quizWrap .choicebox.is-correct:before {
  /* 長い方の線|太さ|タイプ(solid：直線,doubled：二重線,dotted：点線)|色| */
  border-left: 2px solid #25af01;
  /* 短い方の線|太さ|タイプ(solid：直線,doubled：二重線,dotted：点線)|色| */
  border-bottom: 2px solid #25af01;
  /* 左からの距離 */
  left: 18px;
  /* 上からの距離 */
  margin-top: -6px;
  /* 長い方の線の幅 */
  width: 20px;
  /* 短い方の線の幅 */
  height: 10px;
  top: 50%;
  transform: rotate(-45deg) translateY(-50%);
  z-index: 3;
  display: block;
  content: "";
  position: absolute;
}

/* ×マーク */
.quizWrap .choicebox.is-wrong:before,
.quizWrap .choicebox.is-wrong:after {
  /* 色 */
  background-color: #ff0000;
  /* 左からの距離 */
  left: 22px;
  /* 線の幅 */
  height: 20px;
  /* 線の太さ */
  width: 2px;
  top: 50%;
  content: "";
  position: absolute;
  z-index: 3;
}

.quizWrap .choicebox.is-wrong:before {
  transform: translateY(-50%) rotate(45deg);
}
.quizWrap .choicebox.is-wrong:after {
  transform: translateY(-50%) rotate(-45deg);
}

/* 選択肢の文字 */
.quizWrap .choicebox label {
  /* 内側左の余白 */
  padding: 5px 10px;
  /* 高さ */
  width: 100%;
  /* 最小の高さ */
  min-height: 50px;
  /* 左側の枠線|太さ|タイプ(solid：直線,doubled：二重線,dotted：点線)|色| */
  border-left: 1px solid #f4f4f4;
  display: flex;
  align-items: center;
  flex: auto;
  box-sizing: border-box;
}
.quizWrap .choicebox:nth-child(even) label {
  background-color: #fff;
}

