/*画像とカウントダウンが入っている箱の設定*/
.cdt_wrapper {
  /*文字の太さ*/
  font-weight: bold;
  /*文字の位置*/
  text-align: center;
  /*行間*/
  line-height: 2;
  display: flex;
  /*水平方向に間隔を配置する方法。
      flex-start = 左側から配置する
      flex-end = 右側から配置する
      center = 真ん中に配置する
      space-around = 均等配置して両端に間隔を置く
      space-between = 均等配置してエリアの間に間隔を置く
      space-evenly = 均等配置して各アイテム周りに間隔を置く*/
  justify-content: center;
  /*垂直方向にの配置位置を設定。
      center = 中央配置
      flex-start = 先頭にまとめる
      flex-end = 末尾にまとめる*/
  align-items: center;
}



/*リンクを設定した場合*/
a {
  /*下線装飾は無し*/
  text-decoration: none;
}



/*「終了しました」のテキスト設定*/
.cdt_wrapper small {
  /*文字の大きさ*/
  font-size: .6em;
  /*内側の余白｜上下余白｜左右余白｜*/
  padding: 0 .4em;
}



/*カウントダウン部分*/
.cdt {
  display: flex;
  /*垂直方向にの配置位置を設定。
      center = 中央配置
      flex-start = 先頭にまとめる
      flex-end = 末尾にまとめる*/
  align-items: center;
  /*水平方向に間隔を配置する方法。
      flex-start = 左側から配置する
      flex-end = 右側から配置する
      center = 真ん中に配置する
      space-around = 均等配置して両端に間隔を置く
      space-between = 均等配置してエリアの間に間隔を置く
      space-evenly = 均等配置して各アイテム周りに間隔を置く*/
  justify-content: center;
  /*主軸となる方向を定義。
      row = デフォルト、水平方向を基準とし、左から右に配置
      row-reverse = 水平方向を基準とし、右から左に配置
      column =  垂直方向を基準とし、上から下に配置
      column-reverse = 垂直方向を基準とし、下から上に配置*/
  flex-direction: column;
}



